private ArrayList<Object> parseList(LineNumberReader reader) throws IOException {
  ArrayList<Object> list = new ArrayList<>();
  char t;
  boolean readString = false;
  String stringBuffer = new String();
  while (reader.ready()) {
    t = (char) reader.read();
    if (readString) {
      if (t == '"') {
        list.add(stringBuffer);
        stringBuffer = new String();
        readString = false;
      } else {
        stringBuffer += t;
      }
    } else {
      switch (t) {
        case '[': list.add(parseList(reader)); break;
        case ']': return list;
        case '"': readString = true; break;
        case ' ': case '\t': case '\n':
          if (!stringBuffer.isEmpty()) {
            try {
              Double doubleValue = Double.valueOf(stringBuffer);
              list.add(doubleValue);
            } catch (NumberFormatException e) {
              list.add(stringBuffer);
            }
            stringBuffer = new String();
          }
          break;
        default: stringBuffer += t; break;
      }
    }
  }
  return list;
}
